ALTER TABLE public.reservations ADD COLUMN IF NOT EXISTS cleaning_confirm_token text, ADD COLUMN IF NOT EXISTS cleaning_old_monthly_cents integer, ADD COLUMN IF NOT EXISTS cleaning_new_monthly_cents integer, ADD COLUMN IF NOT EXISTS cleaning_confirmed_at timestamptz;
CREATE OR REPLACE FUNCTION public.cleaning_conversion_block(r public.reservations) RETURNS text LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN NOT ('cleaning'=ANY(r.services)) THEN NULL WHEN r.cleaning_verified_at IS NULL THEN 'cleaning_unverified' WHEN r.cleaning_verified_size='custom' THEN 'cleaning_walkthrough_required' WHEN r.cleaning_size_confirmation='pending' THEN 'cleaning_size_unconfirmed' WHEN r.cleaning_size_confirmation='declined' THEN 'cleaning_size_declined' WHEN r.cleaning_verified_size='5' AND NOT r.cleaning_team_ready THEN 'cleaning_needs_team' ELSE NULL END $$;
CREATE OR REPLACE FUNCTION public.guard_cleaning_reservation_conversion() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE reason text; BEGIN IF NEW.status='converted' AND OLD.status IS DISTINCT FROM 'converted' THEN reason:=public.cleaning_conversion_block(NEW); IF reason IS NOT NULL THEN RAISE EXCEPTION '%',reason; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER cleaning_reservation_conversion_guard BEFORE UPDATE OF status ON public.reservations FOR EACH ROW EXECUTE FUNCTION public.guard_cleaning_reservation_conversion();
CREATE OR REPLACE FUNCTION public.admin_cleaning_verify(_reservation uuid,_sqft integer,_baths numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.reservations; verified text; line jsonb; newlines jsonb; amount integer; oldamount integer; total integer; confirm text; BEGIN IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO r FROM public.reservations WHERE id=_reservation FOR UPDATE; IF NOT FOUND OR NOT ('cleaning'=ANY(r.services)) OR r.status IN ('converted','canceled') THEN RAISE EXCEPTION 'reservation_not_verifiable'; END IF; verified:=public.cleaning_size_from_sqft(_sqft,_baths); IF verified IS NULL THEN RAISE EXCEPTION 'invalid_measurement'; END IF; SELECT value INTO line FROM jsonb_array_elements(r.lines) WHERE value->>'service'='cleaning'; oldamount:=round((line->>'monthly')::numeric*100); IF verified='custom' THEN amount:=NULL; confirm:='pending'; ELSE SELECT price_cents INTO amount FROM public.stripe_catalog WHERE canon_key=(CASE verified WHEN '4' THEN 'clean_estate' WHEN '5' THEN 'clean_estateplus' ELSE 'clean_'||verified END)||'_'||(line->>'cadence') AND rate_card_version=coalesce(r.rate_card_version,1) AND active; IF amount IS NULL THEN RAISE EXCEPTION 'locked_catalog_price_missing'; END IF; confirm:=CASE WHEN amount>oldamount THEN 'pending' ELSE 'not_needed' END; END IF; IF confirm='not_needed' THEN SELECT jsonb_agg(CASE WHEN value->>'service'='cleaning' THEN value||jsonb_build_object('size',verified::integer,'monthly',amount::numeric/100) ELSE value END) INTO newlines FROM jsonb_array_elements(r.lines); SELECT round(sum((value->>'monthly')::numeric)*100) INTO total FROM jsonb_array_elements(newlines) WHERE value->>'size'<>'quote'; END IF; UPDATE public.reservations SET cleaning_measured_sqft=_sqft,cleaning_verified_bathrooms=_baths,cleaning_verified_size=verified,cleaning_verified_at=now(),cleaning_verified_by=auth.uid(),cleaning_size_confirmation=confirm,cleaning_confirm_token=CASE WHEN confirm='pending' THEN encode(gen_random_bytes(24),'hex') ELSE NULL END,cleaning_old_monthly_cents=oldamount,cleaning_new_monthly_cents=amount,lines=coalesce(newlines,lines),monthly_cents=coalesce(total,monthly_cents),updated_at=now() WHERE id=r.id; RETURN jsonb_build_object('verified_size',verified,'confirmation',confirm,'old_monthly_cents',oldamount,'new_monthly_cents',amount); END $$;
REVOKE ALL ON FUNCTION public.admin_cleaning_verify(uuid,integer,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_cleaning_verify(uuid,integer,numeric) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.cleaning_conversion_block(public.reservations) TO authenticated,service_role;